== settle
# Move a claim to SETTLED. A change its status does not allow is refused (409) and writes nothing.
# The user who opened the claim cannot settle it (403), writing nothing. A clerk settling a claim whose
# due is above the clerk limit sends it to PENDING (CLAIM_PENDING) for a steward to approve or reject.
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: check
# A claim dated inside a closed period is refused (409) and writes nothing.
check:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.SettleClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
# Record the change only once it is saved, so a refused change writes no audit line.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimSettled
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
== void
# Move a claim to VOID. A change its status does not allow is refused (409) and writes nothing.
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: check
# A claim dated inside a closed period is refused (409) and writes nothing.
check:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.VoidClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
# Record the change only once it is saved, so a refused change writes no audit line.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimVoided
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
== open
# Move a claim to OPEN. A change its status does not allow is refused (409) and writes nothing.
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: check
# A claim dated inside a closed period is refused (409) and writes nothing.
check:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
