package net.officefloor.hq.app.claim;

/** A claim as shown: its amount with two decimals, its date as yyyy-mm-dd, its status, its number
 *  (null when it has none) and, once settled, its fixed due with two decimals (null while live, or when
 *  no rate applied at settling) and who opened it (null while a draft), and the
 *  number a correction corrects (null for any other claim), and its period number when it was numbered
 *  within its period (null otherwise). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        Integer number, String settledDue, String openedBy, Integer corrects, String periodNumber) {

    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().setScale(2).toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(), claim.getNumber(),
                claim.getSettledDue() == null ? null : claim.getSettledDue().setScale(2).toPlainString(),
                claim.getOpenedBy(), claim.getCorrects(), claim.getPeriodNumber());
    }
}
== ClaimStatus
package net.officefloor.hq.app.claim;

/** A claim's status. It starts DRAFT; DRAFT → OPEN → SETTLED; DRAFT or OPEN → VOID. A clerk settling a claim
 *  whose due is above the clerk limit moves it OPEN → PENDING instead; a steward approves it (PENDING → SETTLED)
 *  or rejects it (PENDING → OPEN). SETTLED and VOID are final. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether a claim in this status may move to {@code to} by opening, settling or voiding it (approving
     *  and rejecting a PENDING claim are checked by {@link #awaitsApproval()}). */
    public boolean canBecome(ClaimStatus to) {
        return switch (to) {
            case OPEN -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN;
            case DRAFT -> false;
        };
    }

    /** Whether a claim in this status waits for a steward to approve or reject it. */
    public boolean awaitsApproval() {
        return this == PENDING;
    }

    /** Whether a claim in this status is live: OPEN, or PENDING (which counts as open everywhere). */
    public boolean live() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status counts toward claimed, due-total and every total. */
    public boolean counts() {
        return live() || this == SETTLED;
    }
}

